#include <iostream>
#include <vector>

// цены, которые укладываются в бюджет
std::vector<int> affordable(const std::vector<int>& prices, int budget) {
    std::vector<int> result;
    for (int price : prices) {
        if (price <= budget) {
            result.push_back(price);
        }
    }
    return result;
}

int main() {
    for (int p : affordable({500, 1500, 999, 2000}, 1000)) {
        std::cout << p << "\n";
    }
}

