#include <cstdlib>
#include <iostream>

// сумма цифр: 1990 -> 1 + 9 + 9 + 0 = 19
int digitSum(long long n) {
    n = std::llabs(n);
    if (n < 10) {
        return static_cast<int>(n);
    }
    return static_cast<int>(n % 10) + digitSum(n / 10);
}

int main() {
    std::cout << digitSum(1990) << "\n";
}

