#include <iostream>
#include <stdexcept>
#include <string>

class StockError : public std::runtime_error {
public:
    StockError(int want, int have)
        : std::runtime_error("не хватает товара: нужно " + std::to_string(want) + ", есть " + std::to_string(have)),
          want(want), have(have) {}
    const int want, have;
};

// резерв товара: остаток или исключение
int reserve(int have, int want) {
    if (want <= 0) {
        throw std::invalid_argument("количество должно быть больше нуля");
    }
    if (want > have) {
        throw StockError(want, have);
    }
    return have - want;
}

int main() {
    std::cout << reserve(10, 3) << "\n";
}

